export type CartStoreItem = {
  product: Product;
  quantity: number;
};

export type CartAdItem = {
  ad: Ad;
};

type CartStore = {
  items: CartStoreItem[];
  adItems: CartAdItem[];
  addItem: (product: Product) => void;
  removeItem: (productId: string) => void;
  increaseItem: (productId: string) => void;
  decreaseItem: (productId: string) => void;
  setItemQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;
  clearAdItems: () => void;
  getItemQuantity: (productId: string) => number;
  getTotalItems: () => number;
  getTotalAmount: () => number;
  getTotalAdItems: () => number;
  getTotalAdAmount: () => number;
  addAdItem: (ad: Ad) => void;
  removeAdItem: (adId: string) => void;
  hasAdItem: (adId: string) => boolean;
};

export const useCartStore = create<CartStore>()(
  persist(
    (set, get) => ({
      items: [],
      adItems: [],

      addAdItem: (ad) => {
        if (get().hasAdItem(ad.id)) return;
        set((state) => ({ adItems: [...state.adItems, { ad }] }));
      },

      removeAdItem: (adId) => {
        set((state) => ({
          adItems: state.adItems.filter((i) => i.ad.id !== adId),
        }));
      },

      hasAdItem: (adId) => {
        return get().adItems.some((i) => i.ad.id === adId);
      },

      addItem: (product) => {
        const currentItem = get().items.find(
          (item) => item.product.id === product.id,
        );

        if (currentItem) {
          get().increaseItem(product.id);
          return;
        }

        set((state) => ({
          items: [
            ...state.items,
            {
              product,
              quantity: 1,
            },
          ],
        }));
      },

      removeItem: (productId) => {
        set((state) => ({
          items: state.items.filter((item) => item.product.id !== productId),
        }));
      },

      increaseItem: (productId) => {
        set((state) => ({
          items: state.items.map((item) =>
            item.product.id === productId
              ? { ...item, quantity: item.quantity + 1 }
              : item,
          ),
        }));
      },

      decreaseItem: (productId) => {
        const currentItem = get().items.find(
          (item) => item.product.id === productId,
        );

        if (!currentItem) {
          return;
        }

        if (currentItem.quantity <= 1) {
          get().removeItem(productId);
          return;
        }

        set((state) => ({
          items: state.items.map((item) =>
            item.product.id === productId
              ? { ...item, quantity: item.quantity - 1 }
              : item,
          ),
        }));
      },

      setItemQuantity: (productId, quantity) => {
        if (quantity <= 0) {
          get().removeItem(productId);
          return;
        }

        set((state) => ({
          items: state.items.map((item) =>
            item.product.id === productId
              ? { ...item, quantity }
              : item,
          ),
        }));
      },

      clearCart: () => {
        set({
          items: [],
        });
      },

      clearAdItems: () => {
        set({
          adItems: [],
        });
      },

      getItemQuantity: (productId) => {
        return (
          get().items.find((item) => item.product.id === productId)?.quantity ??
          0
        );
      },

      getTotalItems: () => {
        return get().items.reduce((sum, item) => sum + item.quantity, 0);
      },

      getTotalAmount: () => {
        return get().items.reduce(
          (sum, item) => sum + item.product.price * item.quantity,
          0,
        );
      },

      getTotalAdItems: () => {
        return get().adItems.length;
      },

      getTotalAdAmount: () => {
        return get().adItems.reduce((sum, item) => sum + item.ad.price, 0);
      },
    }),
    {
      name: 'dna-cart',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        items: state.items,
        adItems: state.adItems,
      }),
    },
  ),
