import { ApiTags } from '@nestjs/swagger';

import { OrderStatus } from '@prisma/client';

import { AuthService } from '../auth/auth.service';
import { PrismaService } from '../prisma/prisma.service';

import { PaymentsService } from './payments.service';
import type { YookassaWebhookPayload } from './types/yookassa.types';

@ApiTags('Payments')
@Controller()
export class PaymentsController {
  constructor(
    private readonly paymentsService: PaymentsService,
    private readonly prismaService: PrismaService,
    private readonly authService: AuthService,
    private readonly configService: ConfigService,
  ) {}

  @Post('orders/:orderId/payment')
  async createPayment(
    @Param('orderId') orderId: string,
    @Headers('authorization') authorizationHeader?: string,
  ) {
    const user = await this.authService.getOptionalMeFromAuthorizationHeader(
      authorizationHeader,
    );

    const order = await this.prismaService.order.findUnique({
      where: { id: orderId },
    });

    if (!order) {
      throw new NotFoundException('Order not found');
    }

    if (user && order.userId && order.userId !== user.id) {
      throw new BadRequestException('Access denied');
    }

    if (order.status !== OrderStatus.AWAITING_PAYMENT) {
      throw new BadRequestException(
        `Cannot initiate payment for order with status ${order.status}`,
      );
    }

    const webAppUrl = this.configService.getOrThrow<string>('WEB_APP_URL');
    const returnUrl = `${webAppUrl}/checkout/result?orderId=${orderId}`;

    const payment = await this.paymentsService.createPayment({
      orderId: order.id,
      amountKopecks: order.totalAmount,
      description: `Заказ №${order.id.slice(0, 8)}`,
      returnUrl,
    });

    await this.prismaService.order.update({
      where: { id: orderId },
      data: { yookassaPaymentId: payment.id },
    });

    const confirmation = payment.confirmation as { type: string; confirmation_token?: string };

    return {
      paymentId: payment.id,
      confirmationToken: confirmation.confirmation_token ?? null,
      status: payment.status,
    };
  }

  @Post('payments/webhook')
  async handleWebhook(@Body() body: unknown) {
    let payload: YookassaWebhookPayload;

    try {
      payload = this.paymentsService.parseWebhook(body);
    } catch {
      throw new BadRequestException('Invalid webhook payload');
    }

    const yookassaPaymentId = payload.object.id;

    const order = await this.prismaService.order.findFirst({
      where: { yookassaPaymentId },
    });

    if (!order) {
      return { received: true };
    }

    if (payload.event === 'payment.succeeded') {
      await this.prismaService.order.update({
        where: { id: order.id },
        data: { status: OrderStatus.PAID },
      });
    } else if (payload.event === 'payment.canceled') {
      await this.prismaService.order.update({
        where: { id: order.id },
        data: { status: OrderStatus.CANCELLED },
      });
    }

    return { received: true };
  }
}
import { useEffect } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { CheckCircle, XCircle, Clock } from 'lucide-react';

import { useCartStore } from '@/entities/cart';
import { Button } from '@/components/ui/Button';

type ResultStatus = 'success' | 'pending' | 'failed';

function getStatus(params: URLSearchParams): ResultStatus {
  const status = params.get('status');

  if (status === 'succeeded' || status === 'success') return 'success';
  if (status === 'canceled' || status === 'failed' || status === 'cancelled') return 'failed';

  return 'pending';
}

const statusConfig: Record<
  ResultStatus,
  { icon: typeof CheckCircle; color: string; title: string; description: string }
> = {
  success: {
    icon: CheckCircle,
    color: 'text-green-500',
    title: 'Оплата прошла успешно',
    description: 'Ваш заказ принят в обработку. Детали заказа доступны в профиле.',
  },
  pending: {
    icon: Clock,
    color: 'text-yellow-500',
    title: 'Платёж обрабатывается',
    description:
      'Мы ожидаем подтверждения от платёжной системы. Статус заказа обновится автоматически.',
  },
  failed: {
    icon: XCircle,
    color: 'text-destructive',
    title: 'Оплата не прошла',
    description:
      'Не удалось провести платёж. Попробуйте ещё раз или выберите другой способ оплаты.',
  },
};

export function CheckoutResultPage() {
  const [searchParams] = useSearchParams();
  const status = getStatus(searchParams);
  const config = statusConfig[status];
  const Icon = config.icon;

  const clearCart = useCartStore((state) => state.clearCart);

  useEffect(() => {
    if (status === 'success') {
      clearCart();
    }
  }, [status, clearCart]);

  return (
    <div className="flex min-h-[60vh] items-center justify-center">
      <div className="mx-auto max-w-md space-y-6 text-center">
        <Icon className={`mx-auto size-16 ${config.color}`} />

        <div className="space-y-2">
          <h1 className="text-2xl font-semibold">{config.title}</h1>
          <p className="text-sm text-muted-foreground">{config.description}</p>
        </div>

        <div className="flex flex-col gap-3 sm:flex-row sm:justify-center">
          {status === 'failed' ? (
            <Button asChild>
              <Link to="/checkout">Вернуться к оформлению</Link>
            </Button>
          ) : (
            <Button asChild>
              <Link to="/profile">Мои заказы</Link>
            </Button>
          )}

          <Button asChild variant="outline">
            <Link to="/">На главную</Link>
          </Button>
        </div>
      </div>
    </div>
  );
}
import { create } from 'zustand';
import { createJSONStorage, persist } from 'zustand/middleware';

import type { FavouriteItem } from '../types/favourite-item';

type FavouriteStore = {
  guestItems: FavouriteItem[];

  addGuestItem: (item: FavouriteItem) => void;
  removeGuestItem: (item: FavouriteItem) => void;
  clearGuestItems: () => void;
  isGuestFavourite: (item: FavouriteItem) => boolean;
};

export const useFavouriteStore = create<FavouriteStore>()(
  persist(
    (set, get) => ({
      guestItems: [],

      addGuestItem: (item) => {
        const already = get().isGuestFavourite(item);
        if (already) return;
        set((state) => ({ guestItems: [...state.guestItems, item] }));
      },

      removeGuestItem: (item) => {
        set((state) => ({
          guestItems: state.guestItems.filter((g) => {
            if (item.productId) return g.productId !== item.productId;
            if (item.adId) return g.adId !== item.adId;
            return true;
          }),
        }));
      },

      clearGuestItems: () => set({ guestItems: [] }),

      isGuestFavourite: (item) => {
        return get().guestItems.some((g) => {
          if (item.productId) return g.productId === item.productId;
          if (item.adId) return g.adId === item.adId;
          return false;
        });
      },
    }),
    {
      name: 'dna-favourites',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({ guestItems: state.guestItems }),
    },
  ),
);
import { useState } from 'react';
import { Link } from 'react-router-dom';
import { useQuery } from '@tanstack/react-query';

import { useAuthStore } from '@/entities/auth';
import { getFavourites, useFavouriteStore } from '@/entities/favourite';
import { PLATFORM_SECTION } from '@/shared/platform';
import { getItemGridClasses } from '@/shared/utils/get-item-grid-classes';
import { SectionHeader } from '@/components/ui/Section';
import { Button } from '@/components/ui/Button';
import { SegmentedControl } from '@/components/ui/SegmentedControl';
import { AdCard } from '@/widgets/AdsListing/components/AdCard';
import { ProductCard } from '@/widgets/Catalog/components/ProductGrid/components/ProductCard';

import { FavouritesEmptyState } from './FavouritesEmptyState';

type Tab = 'products' | 'ads';

export function FavouritesPage() {
  const [tab, setTab] = useState<Tab>('products');
  const accessToken = useAuthStore((state) => state.accessToken);
  const { guestItems } = useFavouriteStore();

  const { data: serverFavourites = [], isPending } = useQuery({
    queryKey: ['favourites', accessToken],
    queryFn: () => getFavourites(accessToken!),
    enabled: Boolean(accessToken),
  });

  const favourites = accessToken ? serverFavourites : [];
  const productFavourites = favourites.filter((f) => f.product);
  const adFavourites = favourites.filter((f) => f.ad);

  const guestProductItems = guestItems.filter((i) => i.productId);
  const guestAdItems = guestItems.filter((i) => i.adId);

  const productCount = accessToken
    ? productFavourites.length
    : guestProductItems.length;
  const adCount = accessToken ? adFavourites.length : guestAdItems.length;

  const isLoading = accessToken && isPending;

  if (!isLoading && productCount === 0 && adCount === 0) {
    return <FavouritesEmptyState />;
  }

  return (
    <div className="space-y-6">
      <SectionHeader
        title="Избранное"
        description="Сохранённые товары маркета и объявления доски."
      />

      <SegmentedControl
        options={[
          { value: 'ads', label: `Доска${adCount > 0 ? ` (${adCount})` : ''}` },
          { value: 'products', label: `Маркет${productCount > 0 ? ` (${productCount})` : ''}` },
        ]}
        value={tab}
        onChange={(v) => setTab(v as Tab)}
      />

      {!accessToken && (guestProductItems.length > 0 || guestAdItems.length > 0) && (
        <p className="rounded-xl border border-border px-4 py-3 text-sm text-muted-foreground">
          Вы не авторизованы — избранное сохранено локально.{' '}
          <Link to="/authorization" className="font-medium underline-offset-4 hover:underline">
            Войдите
          </Link>
          , чтобы синхронизировать его с аккаунтом.
        </p>
      )}

      {isLoading && (
        <p className="text-sm text-muted-foreground">Загружаем избранное...</p>
      )}

      {tab === 'products' && !isLoading && (
        <>
          {!accessToken && guestProductItems.length === 0 && (
            <EmptyState
              text="В избранном нет товаров."
              to="/market/catalog"
              linkLabel="Перейти в каталог"
            />
          )}

          {accessToken && productFavourites.length === 0 && (
            <EmptyState
              text="В избранном нет товаров."
              to="/market/catalog"
              linkLabel="Перейти в каталог"
            />
          )}

          {!accessToken && guestProductItems.length > 0 && (
            <p className="text-sm text-muted-foreground">
              Войдите в аккаунт, чтобы увидеть сохранённые товары здесь.
            </p>
          )}

          {accessToken && productFavourites.length > 0 && (
            <div className={getItemGridClasses()}>
              {productFavourites.map((fav) => (
                <ProductCard
                  key={fav.id}
                  section={PLATFORM_SECTION.MARKET}
                  product={fav.product!}
                />
              ))}
            </div>
          )}
        </>
      )}

      {tab === 'ads' && !isLoading && (
        <>
          {!accessToken && guestAdItems.length === 0 && (
            <EmptyState
              text="В избранном нет объявлений."
              to="/ads/catalog"
              linkLabel="Перейти на доску"
            />
          )}

          {accessToken && adFavourites.length === 0 && (
            <EmptyState
              text="В избранном нет объявлений."
              to="/ads/catalog"
              linkLabel="Перейти на доску"
            />
          )}

          {!accessToken && guestAdItems.length > 0 && (
            <p className="text-sm text-muted-foreground">
              Войдите в аккаунт, чтобы увидеть сохранённые объявления здесь.
            </p>
          )}

          {accessToken && adFavourites.length > 0 && (
            <div className={getItemGridClasses()}>
              {adFavourites.map((fav) => (
                <AdCard key={fav.id} ad={fav.ad!} />
              ))}
            </div>
          )}
        </>
      )}
    </div>
  );
}

function EmptyState({
  text,
  to,
  linkLabel,
}: {
  text: string;
  to: string;
  linkLabel: string;
}) {
  return (
    <div className="rounded-2xl border border-dashed border-border p-8 text-center space-y-4">
      <p className="text-sm text-muted-foreground">{text}</p>
      <Button asChild variant="outline">
        <Link to={to}>{linkLabel}</Link>
      </Button>
    </div>
  );
}

