            >
              <p className="text-sm font-semibold">{block.title}</p>

              <ul className="grid gap-2 p-1">
                {block.items.map((item) => (
                  <ReferralEarningDescriptionItem
                    key={item}
                    item={item}
                    type={block.type}
                  />
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </section>
