import { Link } from 'react-router-dom';
import { Trash2 } from 'lucide-react';

import { Button } from '@/components/ui/Button';
import { cn } from '@/shared/utils/cn';

type CartItemCardProps = {
  href: string;
  imageUrl?: string;
  imageAlt?: string;
  placeholderText?: string;
  title: string;
  category?: React.ReactNode;
  price: React.ReactNode;
  priceMeta?: React.ReactNode;
  actions: React.ReactNode;
  favouriteButton?: React.ReactNode;
  onRemove: () => void;
  className?: string;
};

export function CartItemCard({
  href,
  imageUrl,
  imageAlt,
  placeholderText = 'Нет фото',
  title,
  category,
  price,
  priceMeta,
  actions,
  favouriteButton,
  onRemove,
  className,
}: CartItemCardProps) {
  return (
    <Link to={href} className="block">
      <article
        className={cn(
          'grid gap-0 rounded-2xl border border-border bg-card grid-cols-[72px_minmax(0,1fr)] sm:grid-cols-[120px_minmax(0,1fr)]',
          className,
        )}
      >
        <div className="border-r border-border p-2 sm:p-3">
          <div className="aspect-square overflow-hidden rounded-sm bg-muted">
            {imageUrl ? (
              <img
                src={imageUrl}
                alt={imageAlt ?? title}
                className="h-full w-full object-cover"
              />
            ) : (
              <div className="flex h-full w-full items-center justify-center p-2 text-center text-xs text-muted-foreground sm:p-6 sm:text-sm">
                {placeholderText}
              </div>
            )}
          </div>
        </div>

        <div className="min-w-0 space-y-3 p-2 sm:space-y-4 sm:p-3">
          <div className="flex items-start justify-between gap-4">
            <div className="min-w-0 space-y-0.5 sm:space-y-1">
              <h3 className="line-clamp-2 text-sm font-semibold sm:text-base">
                {title}
              </h3>

              {category}
            </div>

            <div className="shrink-0 text-right">
              {price}
              {priceMeta && (
                <p className="text-xs text-muted-foreground">{priceMeta}</p>
              )}
            </div>
          </div>

          <div className="flex items-end justify-between gap-4">
            {actions}

            <div className="flex items-center gap-1">
              {favouriteButton}

              <Button
                type="button"
                variant="destructive"
                size="icon"
                aria-label="Удалить"
                onClick={(e) => {
                  e.stopPropagation();
                  onRemove();
                }}
              >
                <Trash2 className="size-4" />
              </Button>
            </div>
          </div>
        </div>
      </article>
    </Link>
  );
}import type { CartStoreItem } from '@/entities/cart';
import { FavouriteButton } from '@/entities/favourite';
import { formatPrice } from '@/shared/utils/format-price';
import { ProductQuantityCounter } from '@/widgets/ProductQuantityCounter';

import { calculateCartItemTotal } from '../../logic/calculate-cart-item-total';
import { CartItemCard } from '../CartItemCard/CartItemCard';

type CartProductItemCardProps = {
  item: CartStoreItem;
  onRemove: (productId: string) => void;
};

export function CartProductItemCard({ item, onRemove }: CartProductItemCardProps) {
  const { product, quantity } = item;
  const image = product.images[0];
  const itemTotal = calculateCartItemTotal(item);

  return (
    <CartItemCard
      href={`/market/product/${product.slug}`}
      imageUrl={image?.url}
      imageAlt={image?.alt ?? product.title}
      placeholderText="Нет изображения"
      title={product.title}
      category={
        <p className="text-sm text-muted-foreground">
          {product.category.name}
        </p>
      }
      price={<p className="text-base font-semibold sm:text-lg">{formatPrice(itemTotal)}</p>}
      priceMeta={`${quantity} × ${formatPrice(product.price)}`}
      actions={
        <div
          className="w-36 sm:w-40"
          onClick={(e) => e.stopPropagation()}
        >
          <ProductQuantityCounter productId={product.id} variant="details" />
        </div>
      }
      favouriteButton={
        <FavouriteButton
          item={{ productId: product.id }}
          className="size-8 rounded-lg bg-muted hover:bg-muted/80"
        />
      }
      onRemove={() => onRemove(product.id)}
    />
  );
}
import type { CartAdItem } from '@/entities/cart';
import { FavouriteButton } from '@/entities/favourite';
import { formatPrice } from '@/shared/utils/format-price';
import { LinkifyText } from '@/shared/utils/linkify';

import { CartItemCard } from '../CartItemCard/CartItemCard';

type CartAdItemCardProps = {
  item: CartAdItem;
  onRemove: (adId: string) => void;
};

const contactBadgeClass =
  'inline items-center rounded-md bg-muted/60 px-2 py-1 text-xs font-medium text-foreground transition-colors sm:px-3 sm:py-1.5 sm:text-sm';

function getContactValues(ad: CartAdItem['ad']): string[] {
  return [
    ad.contactPhone,
    ad.contactTelegram,
    ad.contactEmail,
    ad.contactOther,
  ].filter((value): value is string => Boolean(value));
}

export function CartAdItemCard({ item, onRemove }: CartAdItemCardProps) {
  const { ad } = item;
  const image = ad.images?.[0];
  const sellerName = ad.seller?.nickname ?? 'Продавец';
  const contactValues = getContactValues(ad);

  return (
    <CartItemCard
      href={`/ads/ad/${ad.slug}`}
      imageUrl={image?.url}
      imageAlt={image?.alt ?? ad.title}
      title={ad.title}
      category={
        ad.category ? (
          <p className="text-xs text-muted-foreground sm:text-sm">{ad.category.name}</p>
        ) : undefined
      }
      price={<p className="text-base font-semibold sm:text-lg">{formatPrice(ad.price)}</p>}
      priceMeta="Объявление"
      favouriteButton={
        <FavouriteButton
          item={{ adId: ad.id }}
          className="size-8 rounded-lg bg-muted hover:bg-muted/80"
        />
      }
      actions={
        <div
          className="flex flex-col gap-1 rounded-xl text-xs sm:gap-2 sm:text-sm"
          onClick={(e) => e.stopPropagation()}
        >
          <span className="font-medium text-foreground">{sellerName}</span>

          {contactValues.length > 0 ? (
            <div className="flex flex-wrap gap-2">
              {contactValues.map((value, index) => (
                <span key={`${value}-${index}`} className={contactBadgeClass}>
                  <LinkifyText text={value} renderLinks={false} />
                </span>
              ))}
            </div>
          ) : (
            <p className="text-sm text-muted-foreground">Продавец пока не указал контакты.</p>
          )}
        </div>
      }
      onRemove={() => onRemove(ad.id)}
    />
  );
}
